s+='''
#[test]
fn max_message_bytes_is_validated_and_part_of_create_equality() {
    let mut h = Harness::new();
    let create = |v: serde_json::Value| json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": v}});
    for bad in [json!(0), json!(1025), json!("5"), json!(5.5)] {
        assert_eq!(h.err(create(bad)), "InvalidParameterValue");
    }
    h.ok(create(json!(10)));
    h.ok(create(json!(10)));
    assert_eq!(h.err(json!({"Command": "CreateQueue", "QueueName": "q"})), "QueueAlreadyExists");
    assert_eq!(attrs(&mut h, "q")["MaxMessageBytes"], json!(10));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1024}}));
    assert_eq!(attrs(&mut h, "q")["MaxMessageBytes"], json!(1024));
}

#[test]
fn max_message_bytes_limits_sends_in_utf8_bytes_and_spares_old_messages() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    h.ok(send("éé"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(send("ééé")), "InvalidParameterValue");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts["Visible"], json!(2));
    assert_eq!(h.err(send("ab")), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_rule_comes_before_fifo_rules() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q.fifo", "Attributes": {"Fifo": true, "MaxMessageBytes": 2}}));
    // Without GroupId this would be MissingParameter.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "abc"})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "ab"})),
        "MissingParameter"
    );
}
