cat > tests/batches.rs <<'EOF'
mod common;

use common::Harness;
use serde_json::{Value, json};

fn create(h: &mut Harness, name: &str, attributes: Value) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
}

fn send_batch(queue: &str, entries: Value) -> Value {
    json!({"Command": "SendMessageBatch", "QueueName": queue, "Entries": entries})
}

fn delete_batch(queue: &str, entries: Value) -> Value {
    json!({"Command": "DeleteMessageBatch", "QueueName": queue, "Entries": entries})
}

fn error_code(entry: &Value) -> &str {
    entry["error"]["code"].as_str().unwrap()
}

#[test]
fn send_batch_assigns_ids_in_order() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let r = h.ok(send_batch(
        "q",
        json!([{"Id": "a", "Body": "x"}, {"Id": "b", "Body": "y", "DelaySeconds": 5}]),
    ));
    assert_eq!(
        r,
        json!({
            "ok": true,
            "Successful": [{"Id": "a", "MessageId": "m-1"}, {"Id": "b", "MessageId": "m-2"}],
            "Failed": [],
        })
    );
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 1, "InFlight": 0, "Delayed": 1}));
}

#[test]
fn batch_level_errors_follow_the_check_order() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("e{i}"), "Body": "x"})).collect();
    let cases = [
        (json!({"Command": "SendMessageBatch", "Entries": []}), "MissingParameter"),
        (json!({"Command": "SendMessageBatch", "QueueName": "q"}), "MissingParameter"),
        (json!({"Command": "SendMessageBatch", "QueueName": "q", "Entries": {}}), "InvalidParameterValue"),
        (json!({"Command": "SendMessageBatch", "QueueName": 1, "Entries": []}), "InvalidParameterValue"),
        // The lookup comes before the numbered rules.
        (send_batch("nope", json!([])), "QueueDoesNotExist"),
        (send_batch("q", json!([])), "EmptyBatchRequest"),
        (send_batch("q", json!(eleven)), "TooManyEntriesInBatchRequest"),
        // Too many wins over a bad id.
        (send_batch("q", json!(eleven.iter().map(|_| json!(1)).collect::<Vec<_>>())), "TooManyEntriesInBatchRequest"),
        (send_batch("q", json!([1])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Body": "x"}])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Id": null, "Body": "x"}])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Id": 1, "Body": "x"}])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Id": "", "Body": "x"}])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Id": "a b", "Body": "x"}])), "InvalidBatchEntryId"),
        (send_batch("q", json!([{"Id": "a".repeat(81), "Body": "x"}])), "InvalidBatchEntryId"),
